require_once __DIR__.'/lib/staging-common.php';$restoredRoot=Ch247Staging::root($argv[1]??'');$dbBackup=realpath($argv[2]??'');$fileBackup=realpath($argv[3]??'');$output=$argv[4]??null;if(!$dbBackup||!is_readable($dbBackup)||filesize($dbBackup)<100)Ch247Staging::fail('Database backup is missing, unreadable or empty.');if(!$fileBackup||!is_readable($fileBackup)||filesize($fileBackup)<100)Ch247Staging::fail('Application backup is missing, unreadable or empty.');require$restoredRoot.'/init.php';use WHMCS\Database\Capsule;$environment=Ch247Staging::verifyEnvironment($restoredRoot);$database=(string)Capsule::selectOne('select database() as name')->name;$sourceHash=(string)getenv('CH247_SOURCE_DATABASE_HASH');$restoreHash=hash('sha256',$database);$failures=array();if($sourceHash===''||hash_equals($sourceHash,$restoreHash))$failures[]='Restoration must use a separately identified isolated database.';$required=array('tblconfiguration','tblclients','tblproducts','tblhosting','tbldomains','tblinvoices','tblinvoiceitems','tblaccounts','tblcurrencies','tblpricing');$tables=array();foreach($required as$t){$tables[$t]=Capsule::schema()->hasTable($t);if(!$tables[$t])$failures[]='Restored required table missing: '.$t;}$cloud=array();foreach(Capsule::select("show tables like 'mod_cloudhost247_%'")as$row)$cloud[]=array_values((array)$row)[0];sort($cloud);$result=array('schema'=>'cloudhost247-backup-verification/v1','report_type'=>'backup_restore_verification','status'=>$failures?'FAIL':'PASS','environment'=>$environment,'restored_database_hash'=>$restoreHash,'database_backup'=>array('bytes'=>filesize($dbBackup),'sha256'=>hash_file('sha256',$dbBackup),'readable'=>true),'application_backup'=>array('bytes'=>filesize($fileBackup),'sha256'=>hash_file('sha256',$fileBackup),'readable'=>true),'restored_connectivity'=>true,'required_tables'=>$tables,'cloudhost247_tables'=>$cloud,'failures'=>$failures,'integrity_verified_utc'=>gmdate('c'));Ch247Staging::write($result,$output);exit($failures?1: